import 'package:flutter/material.dart'; import 'logbook_ui.dart';
class ProgressStepper extends StatelessWidget { const ProgressStepper({super.key,required this.status}); final String status; @override Widget build(BuildContext context){const steps=['Dibuat','Dikirim','Direview','Selesai']; final active=status=='Disetujui'?3:status=='Perlu Revisi'?2:status=='Menunggu Review'?1:0; return Row(children:List.generate(steps.length,(i)=>Expanded(child:Column(children:[Icon(i<=active?Icons.check_circle_rounded:Icons.circle_outlined,color:i<=active?logbookSuccess:const Color(0xFFCBD5E1),size:20),Text(steps[i],textAlign:TextAlign.center,style:const TextStyle(fontSize:10,color:logbookMuted))])))); } }
